namespace Aw.Sindri.Host.Commands;

/// <summary>The usage text: one line per verb, then the exit codes.</summary>
internal static class Usage
{
    private static readonly string[] _verbs =
    [
        // ---- one line per verb ----
        "usage: sindri [--headless]           start the control plane if it isn't running, then print its summary (never from an agent session)",
        "       sindri serve                  run the control plane in the foreground (what 'sindri' starts; launchd target; refused in an agent session)",
        "       sindri status [--json]        the running control plane's status (exit 1 when it isn't running)",
        "       sindri status --follow [--json]   the status again each time it changes, until Ctrl-C (exit 0), or 1 when Sindri isn't running or stops",
        "       sindri stop                   stop it and release the host lease",
        "       sindri profile validate [--json]",
        "       sindri profile approve [--no-start] [<hash>]   without a hash: show the hash and what changed; with it: approve (needs a terminal); starts the control plane unless --no-start",
        "       sindri views rebuild [--no-start]   replay the ledger into the views (the fix when they stall); starts the control plane unless --no-start",
        "       sindri queue [--json] [--no-start]   the queue's groups, one line per item; exit 1 while the views rebuild or stall; starts the control plane unless --no-start",
        "       sindri ledger [--after N] [--item X] [--type T] [--max N] [--json] [--no-start]   the audit read: one line per event (a human also sees non-public types), then 'next: N' while more remain; starts the control plane unless --no-start",
        "       sindri items [--state <s>] [--repo <r>] [--json] [--no-start]   the item list, the oldest first",
        "       sindri item add <title> [--repo <r>] [--no-start]   create an item: 'ITM-… created (sequence N)'",
        "       sindri item close <item> [--cancelled] [--version <n>] [--no-start]   close an item (id or tracker key) as done, or cancelled; without --version it closes the version it reads first",
        "       sindri open <item> [--agent <id>] [--attach | --resume] [--version <n>] [--no-wait] [--json] [--no-start]   open the item's agent session (claude-code, codex, cursor or an added agent): asks for a launch, waits for the launcher's answer (up to 35 s) and prints how the viewer fared, and the attach command when no window opened; exit 0 started, 1 not running or no answer yet, 2 refused or failed",
        "       sindri request <kind> [--item <item>] <text> [--json] [--no-start]   ask a human (rescope, add-task, note or handback), about an item or none: 'REQ-… filed; DEC-… waits for a human'; it is a session's verb",
        "       sindri requests [--state <s>] [--item <item>] [--json] [--no-start]   the requests, newest first, with their text; exit 1 while the views rebuild or stall",
        "       sindri decisions [--pending | --decided] [--item <item>] [--json] [--no-start]   the decisions: pending oldest first, decided newest first, each with its question and the command that decides it; exit 1 while the views rebuild or stall",
        "       sindri decide <decisionId> <choice> [--note <note>] [--json] [--no-start]   settle a decision (accept or decline): the human's verb, a session is refused (SND-AUTH-002)",
        "       sindri needs-you [--json] [--no-start]   what needs a human: decisions, failures, a drifted profile, each with the command that does it; exit 1 while the views rebuild or stall",
        "       sindri services [--json] [--no-start]   each background service: cadence, paused, last run and next slot, and a running job; exit 1 while the views rebuild or stall; starts the control plane unless --no-start",
        "       sindri services run <name> [--detach] [--json] [--no-start]   run a service now as a job and follow it (Ctrl-C cancels the job, a second Ctrl-C leaves); --detach prints the job id and returns; exit 0 succeeded, 1 failed, cancelled or Sindri stopped, 2 refused or invalid",
        "       sindri services pause|resume <name> [--no-start]   stop or restart a service's scheduled runs: the human's verb, a session is refused (SND-AUTH-002)",
        "       sindri jobs [--state <s>] [--kind <k>] [--json] [--no-start]   the jobs, newest first (states: running, succeeded, failed, cancelled); exit 1 while the views rebuild or stall",
        "       sindri jobs show <jobId> [--json] [--no-start]   one job: who started it, its last 200 lines, how it ended and the command that cancels it",
        "       sindri jobs cancel <jobId> [--no-start]   cancel a running job (SND-JOB-409 when it already ended)",
        "       sindri launch init [--viewer <name>] [--force] [--stdout]   detect this box's terminal and write launcher.json (0600); a file that exists is refused without --force (exit 1); --stdout writes nothing",
        "       sindri launch probe [--detach] [--json]   check the launch targets again (the Check again control): a job on the running control plane that records launch.probed when what it found changed; follows the job as 'services run' does",
        "       sindri launch show [<id>] [--json]   the merged agent catalog: source, resolved bin, argvHash, whether Steps may run it (SL8) and the profile line that approves an entry that will park",
        "       sindri agents [--provider <agent>] [--state <s>] [--repo <r>] [--json]   every live agent session on the box: state, repo and host, and the recently ended ones; reads the running control plane and never starts it; exit 1 when it isn't running or a source failed",
        "       sindri agents show <provider>/<id> [--json]   one session in full: host, lane, launch and, at a terminal, directory and state history (SND-SESSION-404 when none)",
        "       sindri setup [--json]   where setting Sindri up stands: one line per step (repo, profile, workflows, agent, map, Onyx) with what is true now; reads the running control plane and never starts it, and changes nothing; exit 0 when every step is done, 1 when one is still to do, waits for you or failed (or Sindri isn't running), 2 on an error",
        "       sindri doctor [--json]        lease, ledger, views, profile, api, temporal and context checks, and the pinned harness probe; runs without the control plane",
        "       sindri doctor --probe [--harness <name>]  this process's agent variables (names only), ancestry and harness version, as JSON",
        "       sindri onyx status [--json]   where Sindri's Onyx stands (not set up, running with its url and version, or stopped) and whether this box can run the pinned one: docker, compose, memory, disk and port, with the fix for each failure (exit 1: a check needs attention); changes nothing and runs without the control plane",
        "       sindri onyx up [--json]   take this box from nothing to the pinned Onyx running on 127.0.0.1: preflight, verified file fetch, config, digest-pinned pull, start, then your account in the browser, Sindri's admin key (asks for your Onyx login once, not stored) and the profile section with its approval (idempotent, resumable; progress on stderr; exit 1: a step failed or was refused, the error names the fix); the human's verb, a session is refused (SND-AUTH-002)",
        "       sindri onyx down [--json]   stop Sindri's Onyx (containers only: data, images and files are kept); the human's verb, a session is refused (SND-AUTH-002)",
        "       sindri onyx open   open Onyx in the browser: the sign-up page until `onyx up` has recorded your account, then the connectors page; the human's verb, a session is refused (SND-AUTH-002)",
        "       sindri repo status [<path>] [--nudge] [--json]   whether a repo (default: the working directory's, a worktree resolves to its main checkout) is in the approved profile; exit 0 onboarded, 1 not (or no approved profile, or outside git), 2 error; --nudge prints one line when the repo is not onboarded and nothing otherwise, always exits 0; read-only, runs without the control plane",
        "       sindri mcp register [--repo NAME] [--providers claude,codex,cursor|all] [--apply] [--json]   the per-repo registration of /sindri/mcp for Claude Code, Codex and Cursor (Claude Code alone without --providers; --apply: a human at a terminal)",
        "       sindri context query <text> [--node K | --item I | --symbol S | --diff BASE..HEAD [--repo R]] [--depth N] [--hops H] [--budget N] [--draft | --map-version V] [--json]   cited context from the running control plane (exit 1: not running, unknown anchor, refused)",
        "       sindri context show <key> [--json]   one map node (a key, alias or name), its aliases and edges (exit 1: unknown or ambiguous, no map)",
        "       sindri context neighbors <key> [--depth N] [--json]   the nodes within N edges (0-4, default 1) either way",
        "       sindri context path <a> <b> [--json]   the shortest path of at most 8 edges between two nodes",
        "       sindri context eval probes [--file F] [--json]   ask each probe, print precision@5 and citation correctness beside the baseline run (exit 1: regressed, SND-CONTEXT-038; exit 2: a probe's query failed, nothing saved)",
        "       sindri context eval map [--json]         node and link precision on your accept/reject decisions, and the unmapped rate",
        "       sindri context eval purge [--all]        delete eval reports and the as-of map cache older than 90 days (--all: every one, probe baselines too)",
        "       sindri context eval backtest [--arms a,b|all] [--since D] [--until D] [--limit N] [--detach] [--json]   (a job)",
        "       sindri context sources status [--json]   each context source's state and whether sessions may read context",
        "       sindri context map import <file>   check a map file, show its hash, type the challenge it shows ('import map <hash6>') to make it the current map (a terminal only)",
        "       sindri context map export [<path>] [--json]   write the current map under $AW_SINDRI_HOME/context/exports/",
        "       sindri context map status [--anchor <key>] [--json]   the current map version and its counts (with --anchor, the lenses' coverage of that node) (exit 1: no map yet, SND-CONTEXT-030)",
        "       sindri context map review [--list] [--limit N] [--json]   the draft's review queue; at a terminal, the loop (bulk accept, then accept / reject / rename / move / skip each item); with --list, --limit or --json, the queue, read-only",
        "       sindri context map review accept|reject <node|edge:id> | rename <node> <name> | move <node> --under <node> | --undo <id>[,<id>…] | --drop <id> | --repoint <id> --to <node> | --accept-deterministic   one reversible decision (terminal or app)",
        "       sindri context map review --history [--limit N] | --export [<path>] | --apply <file> | merge <node> --into <node> | add <node> <name> [--under <node>] | delete <node>   --apply, merge, add and delete need a terminal and the typed challenge",
        "       sindri context map promote       make the latest draft current when nothing is left to decide (SND-CONTEXT-046); type the challenge at a terminal",
        "       sindri context map propose <file> [--json]   a scoping run's surfaces (run, repo, surfaces) as proposals in the draft; map proposals --run <id> reads where they stand",
        "       sindri context map build [--detach] [--json]   propose the map from the repo into a draft as a job and follow it (Ctrl-C cancels the job, a second Ctrl-C leaves); --detach prints the job id and returns (exit 0 succeeded, 1 failed or cancelled, 2 refused; SND-CONTEXT-040: the heavy-job lock stayed busy)",
        "       sindri context map refresh [--detach] [--json]   build the map, let the cleanup agent settle its review queue and promote it, as a job, with no human step (the context-map-refresh service does this when a mapped repo's checkout moves along its default branch); exit codes as build",
        "       sindri context lenses <anchor>... [--depth <0-4>] [--hops <state,flow,dependency,component>] [--draft | --map-version V] [--json]   the intent, product and code lenses of one or up to 20 nodes, with conflicts and coverage",
        "       sindri context subgraph <key>... [--keys-from <file|->] [--depth <0-4>] [--map-version V] [--json]   the bands, edges, conflicts and coverage of up to 1000 nodes and what they reach; unknown keys are listed as missing",
        "       sindri context history <anchor>... [--since T] [--before T] [--draft | --map-version V] [--json]   the stored records, decisions and landed changes behind up to 20 nodes; --before cuts them to the world as of that time (T: RFC 3339 or YYYY-MM-DD)",
        "       sindri context code <anchor>... [--draft | --map-version V] [--json]   the files, tests, data things and schema files of one or up to 20 nodes, with a lexical search of the repo at the map's commit",
        "       sindri context filemap --repo <repo> [--path <dir>] [--unmapped] [--draft] [--json]   a directory's children with their map status; filemap accept|reject <link-id> decides a suggested file link",
        "       sindri context sources sync [<source>] [--detach] [--json]   sync the intent sources now as a job and follow it (Ctrl-C cancels the job, a second Ctrl-C leaves); --detach prints the job id and returns; a second start while one runs is SND-JOB-409",
        "       sindri recipe validate <file> [--json]   check a recipe in-process: rule lines, then its hash (exit 0 pass, 1 fail, 2 error)",
        "       sindri recipe eval <file> [--json]       run a recipe's eval cases in-process (exit 0 pass, 1 fail, 2 error)",
        "       sindri recipe eval --scaffold <file> [--out <dir>]   print a happy-path eval case for the recipe; a route recipe has a case per path, and --out writes each to <dir>/<case>.jsonl (it refuses to overwrite)",
        "       sindri recipe eval --record <address> --out <file>   an instance's history as an eval case, read from the ledger and the stored facts (no server needed)",
        "       sindri recipe register <file>            register a recipe by hash: 'registered <id>@<hash> (unapproved)'",
        "       sindri recipe show <id|id@hash> [--json]  the recipe's keys, urgency, inputs, outputs, path order and loops (a bare id is the approved version); --json: the served RecipeView",
        "       sindri recipe list [--stale] [--json]    one line per registered recipe; --stale: approved ones that drifted or pin a stale child",
        "       sindri recipe approve <file|id@hash>     preview, then type 'approve <id> <version>' at a terminal: 'approved <id>@<hash12>'",
        "       sindri recipe revoke <id@hash>           preview (parks, cascade, parents), then type 'revoke <id>@<hash12>' at a terminal",
        "       sindri scoping check (<address> | --facts <dir>) [--draft <dir>] [--stage draft|evidence] [--json]   the scoping rules over an instance's facts (through serve) or a directory of fact files; --draft overlays draft files (never inside a git worktree); exit 0 pass, 1 findings, 2 usage, tool error or serve not running",
        "       sindri scoping show (<address> | --facts <dir>) [--json]   the stop view: nine sections, the coverage header and every recorded limit with its fix line",
        "       sindri scoping desk <block id> --facts <dir> --out <dir> [--json]   run a block Step's code (intake, check, challenge-log, record, seed, evidence) and write the report a desk 'complete' takes to <dir>/report.json",
        "       sindri design check (<address> | --facts <dir>) [--scope <dir>] [--repo <dir>] [--style <pack.json>] [--lenses <pack.json>] [--stage draft|evidence] [--json]   the design packet's rules (DSN-*) over a directory of its files; --scope, --repo and the pack flags add the scope packet, the base checkout and the packs; exit 0 pass, 1 findings, 2 usage, tool error or serve not running",
        "       sindri plan check (<address> | --facts <dir>) [--design <dir>] [--repo <dir>] [--stage draft|evidence] [--json]   the plan packet's rules (PLN-*); with --repo a packet directory is validated by aw-packets for PLN-PKT-001",
        "       sindri line desk <design.check|design.evidence|plan.check|plan.evidence> --facts <dir> --out <dir> [--json]   run a line block Step's code and write the report a desk 'complete' takes to <dir>/report.json; an evidence Step writes design-packet/ or plan-packet/ and its hash (--packet-id, --repo-slug, --base-sha, --scope-hash, --design-hash, --parallel, --max-stack when packet.json and the packet facts are not in the directory)",
        "       sindri outbox list [--pending | --dispatched] [--json]   one line per effect, from the ledger's effect rows",
        "       sindri workflow start <recipe> --item <id> [--attempt next] [--fact <key>=<file>]... [--json]   start an approved recipe on an item (exit 0 started or found, 1 not running, 2 invalid, refused or error)",
        "       sindri workflow status <address> [--json]   one instance's state, open runs and waits (exit 0 ok, 1 not running, 2 invalid, refused or error: no such instance, malformed address)",
        "       sindri workflow list [--needs-me | --item <id> | --state <s>] [--query <q>] [--json]   one status header per instance; --needs-me: decisions, then tasks (exit 0 ok, 1 not running, 2 invalid, refused or error)",
        "       sindri workflow events <address> [--follow] [--json]   the instance's events from the ledger, oldest first; --follow keeps reading until interrupted (exit 0 ok, 1 not running, 2 invalid, refused or error)",
        "       sindri workflow answer <address> [--text <t> | --file <f>] [--grant <n> | --grant-tokens <n> | --accept | --reject | --resume] [--nonce <n>] [--json]   answer a parked instance (grant, grant-tokens, accept: type the challenge at a terminal; exit 0 applied, 1 not running, 2 invalid, refused or error)",
        "       sindri workflow command <address> <verb> [--nonce <n>] [--json]   send a recipe command to the instance (exit 0 applied, 1 not running, 2 invalid, refused or error)",
        "       sindri workflow cancel <address> [--nonce <n>] [--json]   cancel the instance (exit 0 applied, 1 not running, 2 invalid, refused or error)",
        "       sindri workflow takeover <address> [--nonce <n>] [--json]   take the instance over: its timer pauses (exit 0 applied, 1 not running, 2 invalid, refused or error)",
        "       sindri workflow handback <address> [--nonce <n>] [--json]   hand a taken-over instance back: its timer resumes (exit 0 applied, 1 not running, 2 invalid, refused or error)",
        "       sindri takeover <item-or-address> [--nonce <n>] [--json]   short form of 'workflow takeover' (a bare item is its latest attempt)",
        "       sindri handback <item-or-address> [--nonce <n>] [--json]   short form of 'workflow handback' (a bare item is its latest attempt)",
        "       sindri workflow complete <address> --run <token> --outcome <o> [--output <fact>=<file>]... [--nonce <n>] [--json]   report an open desk run (exit 0 applied, 1 not running, 2 invalid, refused or error)",
    ];

    internal static readonly string Text = string.Join('\n', [.. _verbs, "exit codes: 0 ok, 1 attention needed, 2 error"]);
}
